#!/usr/bin/env bash
# Generated by scripts/build-diagnostics.py. No credentials are embedded.
set -euo pipefail
export PATH=/usr/sbin:/usr/bin:/sbin:/bin

if [[ $# -eq 1 && ( $1 == --help || $1 == -h ) ]]; then
  cat <<'HELP'
DAO 一键诊断：主站和 Worker VPS 使用同一条命令。
curl -fsSL https://raw.githubusercontent.com/<owner>/DAO-install/main/diagnose.sh | sudo bash
自动识别 /opt/dao/dao 与 /opt/dao-worker/dao-worker；兼容 rc.3 起的离线导出。
默认只在本机打包；追加 --upload --repo <owner>/DAO-diagnostics（或设置 DAO_DIAGNOSTICS_REPO）上传到私有诊断仓库。
--repo owner/repo 指定私有诊断仓库；--token-file PATH 指定 root-only 写入授权文件。
也可配置 /etc/dao-diagnostics/github-token；未配置时隐藏询问 Token，不保存输入。
需要诊断仓库 Contents 读写权限，安装只读 Token 不够；公开脚本不含凭据。
不安装、不重启、不升级。上传后打印诊断编号；失败保留本地包。
默认补充最近 24 小时本地轮转日志、HTTP 审计、应用/代理/数据库 journal，以及 PostgreSQL 实例退出状态和有界日志分类。
--hours 1..168 调整补充采集范围；--until 2026-11-19T04:00:00+08:00 指定补充采集的截止时间。
每来源最多 20000 行/16 MiB，collection.json 明确记录覆盖及截断。
HELP
  exit 0
fi
upload=0
repo=${DAO_DIAGNOSTICS_REPO:-nidieshiwo-dao/DAO-diagnostics}
repo_explicit=0
token_file=
hours=24
until_time=
while (( $# )); do
  case $1 in
    --upload) upload=1; shift ;;
    --hours)
      [[ $# -ge 2 && $2 =~ ^[0-9]{1,3}$ ]] && (( 10#$2 >= 1 && 10#$2 <= 168 )) || { echo '--hours 必须为 1..168。' >&2; exit 1; }
      hours=$((10#$2)); shift 2 ;;
    --until)
      [[ $# -ge 2 && $2 =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(Z|[+-][0-9]{2}:[0-9]{2})$ ]] || { echo '--until 需要带时区的 ISO 8601 时间。' >&2; exit 1; }
      until_time=$2; shift 2 ;;
    --repo|--token-file)
      [[ $# -ge 2 && -n $2 && $2 != --* ]] || { echo '上传参数缺少值。' >&2; exit 1; }
      if [[ $1 == --repo ]]; then repo=$2; repo_explicit=1; else token_file=$2; fi
      shift 2 ;;
    *) echo '不支持该参数；查看帮助：bash diagnose.sh --help' >&2; exit 1 ;;
  esac
done
if (( ! upload )) && [[ -n $token_file || $repo_explicit -eq 1 ]]; then
  echo '--repo 和 --token-file 需要配合 --upload。' >&2
  exit 1
fi
if (( upload )) && [[ -z $repo ]]; then
  echo '使用 --upload 时请通过 --repo owner/repo 或环境变量 DAO_DIAGNOSTICS_REPO 指定私有诊断仓库。' >&2
  exit 1
fi
[[ $EUID -eq 0 ]] || { echo '请使用 sudo bash 或 root 运行，以读取服务日志。' >&2; exit 1; }
[[ $(uname -s) == Linux ]] || { echo '仅支持 Linux。' >&2; exit 1; }
for cmd in mktemp mkdir timeout tar chmod date; do
  command -v "$cmd" >/dev/null || { echo "缺少命令：$cmd；未执行收集。" >&2; exit 1; }
done
if [[ ! -x /opt/dao/dao && ! -x /opt/dao-worker/dao-worker ]]; then
  echo '未找到一键安装的 DAO 主站或 Worker；请在对应 VPS 上运行。' >&2
  exit 1
fi

umask 077
work=$(mktemp -d /tmp/dao-check.XXXXXX)
contents=$work/contents
mkdir "$contents" "$work/native"
trap 'printf "诊断打包未完成；已收集的信息保留在：%s\n" "$work" >&2' ERR

status() {
  local label=$1
  shift
  printf '\n[%s]\n' "$label"
  if timeout -k 2s 15s "$@" </dev/null; then
    :
  else
    printf '未能完整读取此项（退出码 %s），不代表其他项目失败。\n' "$?"
  fi
}
{
  status time date -Is
  status system uname -srmo
  status uptime uptime
  status memory free -h
  status disk df -h / /var/lib /tmp
  status services systemctl show dao dao-worker dao-https postgresql \
    -p Id -p LoadState -p ActiveState -p SubState -p Result \
    -p NRestarts -p ExecMainStatus -p ActiveEnterTimestamp \
    -p MainPID -p MemoryCurrent -p TasksCurrent
  status database-services systemctl list-units --all --type=service \
    --no-pager --plain --no-legend 'postgresql@*.service'
} >"$contents/status.txt" 2>&1

failures=0
roles=
export_logs() {
  local role=$1
  shift
  printf '正在收集 %s 的近期日志……\n' "$role"
  if timeout -k 2s 30s "$@" -diagnostics "$work/native/$role.zip" \
      </dev/null >"$work/native/$role-export.txt" 2>&1; then
    if [[ -s $work/native/$role.zip ]]; then
      printf '原生导出完成；过滤结果见 collection.json。\n' >"$contents/$role-export.txt"
      return
    fi
    printf '程序未生成诊断包。\n' >>"$contents/$role-export.txt"
  fi
  printf '原生导出失败，详细命令输出仅留本机。\n' >>"$contents/$role-export.txt"
  failures=$((failures + 1))
  printf '%s 日志导出未完成，错误记录将随状态信息一起打包。\n' "$role"
}
if [[ -x /opt/dao/dao ]]; then
  roles=main
  export_logs main /opt/dao/dao -data /var/lib/dao/data
fi
if [[ -x /opt/dao-worker/dao-worker ]]; then
  roles=${roles:+$roles-}worker
  export_logs worker /opt/dao-worker/dao-worker -config /etc/dao-worker/config.json
fi

if command -v python3 >/dev/null; then
  if ! python3 - "$contents" "$roles" "$hours" "$until_time" <<'DAO_DIAGNOSTIC_COLLECT_PYTHON'
"""Bounded, read-only diagnostic supplement; works with already installed rc.3.

Only whitelisted log files/journal fields are copied. Never dumps environment,
command lines, databases, task files or the contents of Worker configuration.
"""
from array import array
from contextlib import ExitStack
import datetime as dt
import json
import os
from pathlib import Path
import re
import stat
import subprocess
import sys
import tempfile
import time
import zipfile

MAX_BYTES = 16 << 20
MAX_LINES = 20000
JOURNAL_TIMEOUT = 15
MAX_DATABASE_UNITS = 16
SECRETS = [
    re.compile(r"(?s)-----BEGIN [A-Z ]*PRIVATE KEY-----.*?-----END [A-Z ]*PRIVATE KEY-----"),
    re.compile(r"(?i)\b(?:Bearer|Basic)\s+[a-z0-9._~+/=-]+"),
    re.compile(r"\b(?:github_pat_|gh[pousr]_|sk-)[A-Za-z0-9_-]{12,}"),
    re.compile(r"\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+"),
]
PAIR = re.compile(r'''(?i)(["']?(?:api[-_]?key|access[-_]?token|refresh[-_]?token|token|password|passwd|secret|authorization|cookie|set-cookie|database_dsn|dsn|private_key)["']?\s*[:=]\s*)("(?:\\.|[^"\\])*"|'[^']*'|[^\s,;&]+)''')

def redact(value):
    if isinstance(value, dict):
        return {k: ("[REDACTED]" if re.fullmatch(r"(?i)(password|token|authorization|cookie|set-cookie|api_key|database_dsn|secret)", k) else redact(v)) for k,v in value.items()}
    if isinstance(value, list):
        return [redact(v) for v in value]
    if not isinstance(value, str):
        return value
    value = re.sub(r"(\[task\] 新建任务 #[0-9]+) .*", r"\1 [content omitted]", value, flags=re.S)
    value = re.sub(r"\[llm-test\] [^\r\n]*? / .*", "[llm-test] [content omitted]", value, flags=re.S)
    value = re.sub(r"(^|[\t \n])响应体: .*", r"\1[llm-test] [content omitted]", value, flags=re.S)
    value = re.sub(r"([a-zA-Z][a-zA-Z0-9+.-]*://)[^\s/@]+@", r"\1[REDACTED]@", value)
    for pattern in SECRETS:
        value = pattern.sub("[REDACTED]", value)
    value = PAIR.sub(r'\1"[REDACTED]"', value)
    # Journal messages may contain Caddy request URIs. Queries can carry a JWT.
    value = re.sub(r"((?:https?://[^\s\"']+|/api/[^\s\"'?]+))\?[^\s\"']*", r"\1?[QUERY REMOVED]", value)
    return value[:8192] + (" [truncated]" if len(value)>8192 else "")

def parse_time(value):
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
        return parsed.astimezone(dt.timezone.utc) if parsed.tzinfo else None
    except (ValueError, TypeError, AttributeError):
        return None

def regular_open(path, root):
    # Anchor directory traversal to descriptors: no symlink escape or FIFO wait,
    # including a directory replaced while the root collector is reading it.
    parts=path.relative_to(root).parts
    if not parts or any(p in ("..", ".") for p in parts): raise ValueError("invalid log path")
    directory=os.open(root.resolve(),os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:
        for part in parts[:-1]:
            child=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=directory)
            os.close(directory);directory=child
        fd = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,dir_fd=directory)
    finally: os.close(directory)
    if not stat.S_ISREG(os.fstat(fd).st_mode):
        os.close(fd)
        raise ValueError("not a regular log file")
    return os.fdopen(fd,"rb")

def fair_shares(sizes, budget):
    """Small groups keep their allowance; large groups share what remains."""
    shares = [0] * len(sizes)
    order = sorted(range(len(sizes)), key=lambda i: sizes[i])
    for step, i in enumerate(order):
        shares[i] = min(sizes[i], budget // (len(order) - step))
        budget -= shares[i]
    return shares


def read_ranges(size, allowance):
    if size <= allowance:
        return [(0, size)]
    if not allowance:
        return []
    # Sample the beginning, interior and end of a large rotation.
    count = min(8, max(2, allowance // (64 << 10)), allowance)
    lengths = fair_shares([size] * count, allowance)
    offset = 0
    ranges = []
    for i, length in enumerate(lengths):
        start = offset + i * (size - allowance) // max(count - 1, 1)
        ranges.append((start, length))
        offset += length
    return ranges


SYSTEM_FIELDS = ("ts", "instance", "seq", "db_id", "level", "tag", "text")
AUDIT_FIELDS = ("ts", "event", "level", "request_id", "method", "route", "status", "code",
                "client_ip", "user_agent", "task_id", "node_id", "elapsed_ms", "count", "first_at", "session_ref",
                "edge_id", "protocol", "failure_stage")


def evidence_family(row):
    # Keep summaries low cardinality; do not use arbitrary log text or IDs as keys.
    if "text" in row:
        level = row.get("level")
        return level if level in ("info", "warn", "error", "debug") else "other"
    event = row.get("event")
    if event in ("auth.session.accepted", "auth.setup.success", "auth.login.success", "auth.basic.rejected"):
        return event
    status = row.get("status")
    return "http_%dxx" % (status // 100) if type(status) is int and 100 <= status < 600 else "other"


def collect_files(root, relative, since, output, until=None):
    until = until or dt.datetime.now(dt.timezone.utc)
    bucket_count = 8
    span = (until - since) / bucket_count
    if span <= dt.timedelta(0):
        raise ValueError("empty collection interval")
    report = {"source": relative, "files": [], "lines": 0, "bytes_read": 0, "invalid_lines": 0,
              "truncated": False, "issues": [], "retention_before_first_observation": "unknown"}
    # Only complete, in-range JSONL records enter this <= input-budget buffer.
    # Compact offsets avoid retaining one Python dict per input line in a flood.
    records = bytearray()
    offsets = {}
    groups = {}
    def scan(data):
        for raw in data.splitlines():
            try:
                row = json.loads(raw)
            except (ValueError, UnicodeError):
                row = None
            at = parse_time(row.get("ts")) if isinstance(row, dict) else None
            if at is None:
                report["invalid_lines"] += 1
                continue
            if not since <= at <= until:
                continue
            key = (min(bucket_count - 1, (at - since) // span), evidence_family(row))
            if key not in offsets:
                offsets[key] = array("I")
                groups[key] = {"observed": 0, "emitted": 0, "first_at": at, "last_at": at}
            offsets[key].append(len(records))
            records.extend(raw)
            records.append(10)
            group = groups[key]
            group["observed"] += 1
            group["first_at"] = min(group["first_at"], at)
            group["last_at"] = max(group["last_at"], at)

    with ExitStack() as files:
        sources = []
        for suffix in (".3", ".2", ".1", ""):
            path = Path(root) / relative / ("system.jsonl" + suffix)
            try:
                stream = files.enter_context(regular_open(path, Path(root)))
                sources.append((path.name, stream, os.fstat(stream.fileno()).st_size))
            except FileNotFoundError:
                continue
            except (OSError, ValueError) as error:
                report["issues"].append(redact(str(error)))
        shares = fair_shares([size for _, _, size in sources], MAX_BYTES)
        for (name, stream, size), allowance in zip(sources, shares):
            ranges = read_ranges(size, allowance)
            item = {"name": name, "size": size, "bytes_read": 0, "read_ranges": [], "unread_bytes": size}
            report["files"].append(item)
            for start, length in ranges:
                try:
                    stream.seek(start)
                    data = stream.read(length)
                except OSError as error:
                    report["issues"].append(redact(str(error)))
                    break
                item["bytes_read"] += len(data)
                item["unread_bytes"] -= len(data)
                item["read_ranges"].append([start, start + len(data)])
                if start:
                    data = data.partition(b"\n")[2]
                end = data.rfind(b"\n")
                if end + 1 != len(data):
                    report["truncated"] = True
                if end >= 0:
                    scan(data[:end])
            report["bytes_read"] += item["bytes_read"]
            report["truncated"] |= item["unread_bytes"] > 0

    keys = sorted(offsets)
    shares = fair_shares([len(offsets[k]) for k in keys], MAX_LINES)
    # Budget extremal examples before interior examples, then emit in original order.
    candidates = []
    for key, share in zip(keys, shares):
        positions = offsets[key]
        for i in range(share):
            index = i * (len(positions) - 1) // max(1, share - 1)
            priority = int(i != 0 and i != share - 1)
            candidates.append((priority, positions[index], key))
    remaining = MAX_BYTES
    selected = []
    for _, pos, key in sorted(candidates):
        row = json.loads(records[pos:records.index(10, pos)])
        fields = SYSTEM_FIELDS if "text" in row else AUDIT_FIELDS
        row = redact({field: row[field] for field in fields if field in row})
        if "session_ref" in row and not (isinstance(row["session_ref"], str) and re.fullmatch(r"[0-9a-f]{32}", row["session_ref"])):
            del row["session_ref"]
        if not isinstance(row.get("edge_id"), str) or not EDGE_UUID.fullmatch(row["edge_id"]):
            row.pop("edge_id", None)
        if row.get("protocol") not in HTTP_PROTOCOLS:
            row.pop("protocol", None)
        if row.get("failure_stage") not in ("node_binding", "node_connect", "node_owner", "node_setup",
                                           "node_configuration", "node_authority", "node_open",
                                           "node_headers", "node_body_read", "node_body_decode",
                                           "response_write", "response_flush", "handler_abort"):
            row.pop("failure_stage", None)
        line = (json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n").encode()
        if len(line) <= remaining:
            selected.append((pos, row["ts"], line))
            groups[key]["emitted"] += 1
            remaining -= len(line)
    selected.sort()
    with open(output, "wb") as out:
        for _, _, line in selected:
            out.write(line)
    report["first_at"] = selected[0][1] if selected else None
    report["last_at"] = selected[-1][1] if selected else None
    report["available"] = bool(report["files"])
    report["lines"] = len(selected)
    report["observed_lines"] = sum(group["observed"] for group in groups.values())
    report["truncated"] |= len(selected) < report["observed_lines"]
    report["windows"] = []
    for i in range(bucket_count):
        families = {}
        for (bucket, family), group in groups.items():
            if bucket == i:
                families[family] = dict(group, first_at=group["first_at"].isoformat(), last_at=group["last_at"].isoformat())
        report["windows"].append({"from": (since + i * span).isoformat(),
                                  "to": (until if i == bucket_count - 1 else since + (i + 1) * span).isoformat(),
                                  "families": families, "evidence": "observed" if families else "no_observed_records"})
    return report

def database_units(status_path):
    # The shell entrypoint already enumerated loaded (including failed/inactive)
    # database units. Reuse that bounded snapshot, not journalctl's glob search
    # over all historical unit names, which can exhaust the timeout on a VPS.
    units={"postgresql.service"}
    issues=[]
    try:
        with regular_open(status_path,status_path.parent) as f:
            data=f.read((64 << 10)+1)
        if len(data)>64 << 10: raise ValueError("service status exceeds read limit")
        section=False;found=False
        for line in data.decode("utf-8",errors="replace").splitlines():
            if line.startswith("["):
                section=line=="[database-services]";found |= section
                continue
            if not section or not line.strip(): continue
            name=line.split()[0]
            if re.fullmatch(r"postgresql@[A-Za-z0-9_.\\:-]+\.service",name):
                if name not in units and len(units)>=MAX_DATABASE_UNITS:
                    issues.append("database unit limit reached; some clusters were not collected")
                    break
                units.add(name)
            else:
                issues.append("database unit enumeration incomplete; see status.txt")
        if not found: issues.append("database service status section unavailable")
    except (OSError,ValueError) as error:
        issues.append("database unit enumeration unavailable: "+redact(str(error)))
    return sorted(units),list(dict.fromkeys(issues))

# PostgreSQL file logging on Debian/Ubuntu uses this exact unit/file mapping.
# Escaped systemd names and custom locations are reported as unsupported.
PG_UNIT = re.compile(r"postgresql@(\d{1,3}(?:\.\d{1,2})?)-([A-Za-z0-9_][A-Za-z0-9_.-]{0,63})\.service")
PG_TAIL_BYTES = 256 << 10
PG_ANCHOR_BYTES = 128 << 10
PG_HEADER = re.compile(
    rb"^(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d(?:\.\d{1,6})?)\s*"
    rb"(UTC|GMT|CET|CEST|[+-]\d\d(?::?\d\d)?|[A-Z]{2,6})\s+"
    rb"\[\d+\]\s+(?:[^\s]{1,256}@[^\s]{0,256}\s+)?"
    rb"(DEBUG[1-5]|INFO|NOTICE|WARNING|LOG|ERROR|FATAL|PANIC|DETAIL|HINT|CONTEXT|STATEMENT):\s*(.*)$")
PG_OFFSETS = {b"UTC": "+00:00", b"GMT": "+00:00", b"CET": "+01:00", b"CEST": "+02:00"}
PG_CHECKS = {
    ("assets", "assets_company_source_check"), ("company_scope", "ck_company_scope_payload"),
    ("exploration_nodes", "ck_node_kind"), ("exploration_nodes", "ck_node_state"),
    ("exploration_edges", "ck_edge_noself"), ("exploration_edges", "ck_edge_rel"),
    ("side_question_sessions", "side_question_sessions_check"),
}
PG_CHECK_MESSAGE = re.compile(rb'^new row for relation "([a-z_0-9]{1,63})" violates check constraint "([a-z_0-9]{1,63})"')
PG_TIME_FIELDS = ("ExecMainStartTimestamp", "ExecMainExitTimestamp", "StateChangeTimestamp")
PG_STATE_VALUES = {
    "LoadState": {"stub", "loaded", "not-found", "bad-setting", "error", "merged", "masked"},
    "ActiveState": {"inactive", "activating", "active", "reloading", "deactivating", "failed", "maintenance", "refreshing"},
    "SubState": {"dead", "start-pre", "start", "start-post", "running", "exited", "reload", "stop",
                 "stop-sigterm", "stop-sigkill", "stop-post", "failed", "auto-restart", "cleaning"},
    "Result": {"success", "exit-code", "signal", "core-dump", "timeout", "watchdog", "resources",
               "protocol", "start-limit-hit", "oom-kill", "exec-condition"},
}


def pg_header_time(match):
    zone = match[2]
    offset = PG_OFFSETS.get(zone)
    if offset is None:
        if zone[:1] not in (b"+", b"-"):
            return None
        offset = zone.decode()
        if len(offset) == 3:
            offset += ":00"
    return parse_time(match[1].decode() + offset)


def pg_message_class(level, body):
    # Emitted labels are fixed. Arbitrary error messages, usernames, PIDs,
    # relation names, query strings and continuation lines never become output.
    lower = body[:8192].lower()
    if level == "ERROR" and lower.startswith(b"new row for relation ") and b"violates check constraint" in lower:
        return "check_violation"
    if level == "FATAL" and (b"authentication failed" in lower or lower.startswith(b"no pg_hba.conf entry")
                             or lower.startswith(b"role ") and b"does not exist" in lower):
        return "login_rejected"
    if level in ("ERROR", "FATAL", "PANIC"):
        for fragment, category in ((b"no space left on device", "disk_full"), (b"read-only file system", "read_only_filesystem"),
                                   (b"out of memory", "memory_error"), (b"permission denied", "permission_denied"),
                                   (b"checksum mismatch", "checksum_error")):
            if fragment in lower:
                return category
        return "other_error"
    if level == "LOG":
        if lower.startswith((b"server process (pid ", b"background worker ")) and b"was terminated by signal" in lower:
            return "process_signaled"
        if lower.startswith(b"received ") and b"shutdown request" in lower:
            return "shutdown_requested"
        if lower.startswith(b"database system is shut down"):
            return "shutdown_completed"
        if lower.startswith(b"database system is ready to accept connections"):
            return "ready"
    return None


def postgres_service_states(units):
    """Read current/last systemd state in one bounded call, using only scalar properties."""
    states, issues = {}, []
    fields = ("Id", *PG_STATE_VALUES, "ExecMainCode", "ExecMainStatus", *PG_TIME_FIELDS)
    args = ["systemctl", "show", "--all", "--no-pager", "--property=" + ",".join(fields), *units]
    try:
        with tempfile.TemporaryFile() as output:
            result = subprocess.run(args, stdout=output, stderr=subprocess.DEVNULL, timeout=5,
                                    env={**os.environ, "TZ":"UTC", "LC_ALL":"C"})
            output.seek(0)
            body = output.read(65537)
    except (OSError, subprocess.TimeoutExpired):
        return {}, ["instance manager unavailable or timed out"]
    if result.returncode != 0:
        issues.append("systemctl show did not complete for all instances")
    for block in body[:65536].decode(errors="replace").strip().split("\n\n"):
        props = dict(line.split("=", 1) for line in block.splitlines() if "=" in line)
        if props.get("Id") not in units:
            continue
        state = {}
        for field, allowed in PG_STATE_VALUES.items():
            val = props.get(field, "")
            if val:
                state[field] = val if val in allowed else "unknown"
        for field in ("ExecMainCode", "ExecMainStatus"):
            val = props.get(field, "")
            if re.fullmatch(r"\d{1,5}", val):
                state[field] = int(val)
        for field in PG_TIME_FIELDS:
            val = props.get(field, "")
            try:
                at = dt.datetime.strptime(val, "%a %Y-%m-%d %H:%M:%S UTC")
            except ValueError:
                continue
            state[field] = at.replace(tzinfo=dt.timezone.utc).isoformat()
        states[props["Id"]] = state
    if len(body) > 65536 or any(not states.get(unit, {}).get("Result") for unit in units):
        issues.append("instance state fields unavailable")
    return states, issues


def pg_log_ranges(stream, size, anchor):
    # Always inspect the tail. Large files also get a bounded search for the
    # last exit (or requested --until), useful after restart and later writes.
    ranges = [(max(0, size - PG_TAIL_BYTES), size)]
    probe_bytes = 0
    if size > PG_TAIL_BYTES:
        lo, hi = 0, size
        for _ in range(16):
            if hi - lo <= PG_ANCHOR_BYTES:
                break
            mid = (lo + hi) // 2
            stream.seek(mid)
            probe = stream.read(4096)
            probe_bytes += len(probe)
            stamp = None
            for line in probe.split(b"\n")[1:-1]:
                match = PG_HEADER.match(line)
                if match:
                    stamp = pg_header_time(match)
                    if stamp:
                        break
            if stamp is None:
                break
            if stamp < anchor:
                lo = mid
            else:
                hi = mid
        end = min(size, (lo + hi) // 2 + PG_ANCHOR_BYTES // 4)
        ranges.append((max(0, end - PG_ANCHOR_BYTES), end))
    merged = []
    for start, end in sorted(ranges):
        if merged and merged[-1][1] >= start:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged, probe_bytes


def pg_log_summary(root, stem, since, until, anchor, *, exit_time=None):
    events, files, issues = {}, [], []
    exit_samples = {}
    partial = False
    for suffix in (".log.1", ".log"):
        try:
            with regular_open(root / (stem + suffix), root.parent) as stream:
                before = os.fstat(stream.fileno())
                size = before.st_size
                ranges, probe_bytes = pg_log_ranges(stream, size, anchor)
                file = {"rotation": "previous" if suffix.endswith(".1") else "current", "size": size,
                        "modified_at": dt.datetime.fromtimestamp(before.st_mtime, dt.timezone.utc).isoformat(),
                        "bytes_read": probe_bytes, "sample_ranges": ranges, "matched_headers": 0,
                        "unresolved_timezone": 0}
                files.append(file)
                sampled = 0
                for start, end in ranges:
                    stream.seek(start)
                    data = stream.read(end - start)
                    sampled += len(data)
                    file["bytes_read"] += len(data)
                    if start:
                        data = data.partition(b"\n")[2]
                    if data and not data.endswith(b"\n"):
                        partial = True
                    for line in data.split(b"\n")[:-1]:
                        match = PG_HEADER.match(line)
                        if not match:
                            continue
                        file["matched_headers"] += 1
                        stamp = pg_header_time(match)
                        if stamp is None:
                            file["unresolved_timezone"] += 1
                            continue
                        if not since <= stamp <= until:
                            continue
                        level = match[3].decode()
                        category = pg_message_class(level, match[4])
                        if not category:
                            continue
                        schema_group = None
                        if category == "check_violation":
                            names = PG_CHECK_MESSAGE.match(match[4])
                            if names:
                                pair = (names[1].decode(), names[2].decode())
                                if pair in PG_CHECKS:
                                    schema_group = ".".join(pair)
                        key = (level, category, schema_group)
                        at = stamp.isoformat()
                        if key not in events:
                            events[key] = {"level":level, "class":category, "at":at, "last_at":at, "count":0}
                            if schema_group:
                                events[key]["schema_group"] = schema_group
                        group = events[key]
                        group["at"] = min(group["at"], at)
                        group["last_at"] = max(group["last_at"], at)
                        group["count"] += 1
                        if exit_time is not None:
                            # systemctl show provides second-resolution timestamps.
                            offset = int((stamp.replace(microsecond=0) - exit_time).total_seconds())
                            side = "before" if offset < 0 else "after" if offset > 0 else "same_second"
                            prior = exit_samples.get(side)
                            if prior is None or abs(offset) < abs(prior["seconds_from_exit"]):
                                prior = {"seconds_from_exit": offset, "classes": set()}
                                exit_samples[side] = prior
                            if offset == prior["seconds_from_exit"]:
                                prior["classes"].add(category)
                after = os.fstat(stream.fileno())
                file["changed_during_read"] = (after.st_size, after.st_mtime_ns) != (size, before.st_mtime_ns)
                partial |= (sampled < size or file["changed_during_read"] or bool(file["unresolved_timezone"])
                            or bool(size and not file["matched_headers"]))
        except FileNotFoundError:
            if suffix == ".log":
                issues.append("current default log unavailable")
        except (OSError, ValueError):
            issues.append("default log unreadable or not a regular file")
    for item in exit_samples.values():
        item["classes"] = sorted(item["classes"])
    return {"events":sorted(events.values(), key=lambda v:v["at"]), "files":files, "issues":issues,
            "nearest_observed_exit_seconds": exit_samples,
            "partial":partial or bool(issues), "earlier_history":"unknown"}


PG_WAL_ENTRY_LIMIT = 4096
PG_WAL_SECONDS = 2.0


def default_wal_space(data_root, unit, deadline):
    """Stat default-layout WAL segment files without following links or opening segments."""
    sample = {"scope": "debian_default_cluster_directory", "available": False, "partial": True,
              "entries_seen": 0, "entry_limit": PG_WAL_ENTRY_LIMIT, "issues": [],
              "observed_segments": None, "observed_apparent_bytes": None, "observed_allocated_bytes": None}
    cluster = PG_UNIT.fullmatch(unit)
    directory = None
    if not cluster or not data_root.is_absolute() or ".." in data_root.parts:
        sample["issues"].append("unsupported default layout")
        return sample
    if time.monotonic() >= deadline:
        sample["issues"].append("shared WAL sampling deadline reached")
        return sample
    try:
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
        directory = os.open("/", flags)
        for part in (*data_root.parts[1:], *cluster.groups(), "pg_wal"):
            child = os.open(part, flags, dir_fd=directory)
            os.close(directory)
            directory = child
        before = os.fstat(directory)
        seen = set()
        apparent = allocated = 0
        with os.scandir(directory) as entries:
            for entry in entries:
                if time.monotonic() >= deadline or sample["entries_seen"] >= PG_WAL_ENTRY_LIMIT:
                    sample["issues"].append("WAL sampling limit reached")
                    break
                sample["entries_seen"] += 1
                if not re.fullmatch(r"[0-9A-F]{24}(?:\.partial)?", entry.name):
                    continue
                try:
                    info = entry.stat(follow_symlinks=False)
                except OSError:
                    sample["issues"].append("segment metadata unavailable")
                    continue
                if not stat.S_ISREG(info.st_mode):
                    sample["issues"].append("non-regular segment omitted")
                    continue
                identity = (info.st_dev, info.st_ino)
                if identity not in seen:
                    seen.add(identity)
                    apparent += info.st_size
                    allocated += info.st_blocks * 512
        if os.fstat(directory).st_mtime_ns != before.st_mtime_ns:
            sample["issues"].append("directory changed during scan")
        sample.update(available=True, observed_segments=len(seen), observed_apparent_bytes=apparent,
                      observed_allocated_bytes=allocated)
    except OSError:
        sample["issues"].append("default directory unavailable or not accessible without following links")
    finally:
        if directory is not None:
            os.close(directory)
    sample["issues"] = list(dict.fromkeys(sample["issues"]))
    sample["partial"] = bool(sample["issues"])
    return sample


def collect_postgres_exit(units, since, until, *, log_root=Path("/var/log/postgresql"), data_root=Path("/var/lib/postgresql")):
    concrete = sorted({name for name in units if re.fullmatch(r"postgresql@[A-Za-z0-9_.\\:-]{1,128}\.service", name)})[:MAX_DATABASE_UNITS]
    states, issues = postgres_service_states(concrete) if concrete else ({}, [])
    if not concrete:
        issues.append("no concrete default PostgreSQL cluster identified")
    report = {"clusters":{}, "root_cause":"undetermined", "since":since.isoformat(), "until":until.isoformat(),
              "state_observed_at":dt.datetime.now(dt.timezone.utc).isoformat(), "issues":issues, "partial":bool(issues)}
    wal_deadline = time.monotonic() + PG_WAL_SECONDS
    wal_by_unit = {unit: default_wal_space(data_root, unit, wal_deadline) for unit in concrete}
    for unit in concrete:
        service = states.get(unit, {})
        exited = parse_time(service.get("ExecMainExitTimestamp"))
        observed_exit = exited if exited and since <= exited <= until else None
        anchor = observed_exit or until
        default_name = PG_UNIT.fullmatch(unit)
        if default_name:
            version, cluster = default_name.groups()
            log = pg_log_summary(log_root, f"postgresql-{version}-{cluster}", since, until, anchor, exit_time=observed_exit)
        else:
            log = {"events": [], "files": [], "partial": True, "issues": ["unsupported default log mapping"]}
        missing = []
        if service.get("ActiveState") == "failed":
            missing = [field for field in ("Result", "ExecMainCode", "ExecMainStatus", "ExecMainExitTimestamp")
                       if service.get(field) in (None, "", "unknown")]
        wal = wal_by_unit[unit]
        report["clusters"][unit] = {"service": service, "missing_exit_fields": missing, "wal_space": wal,
                                    "sample_anchor": anchor.isoformat(),
                                    "anchor_source": "last_process_exit" if observed_exit else "window_end",
                                    "log": log}
        report["partial"] |= log["partial"] or wal["partial"] or bool(missing)
    return report


EDGE_UUID = re.compile(r"[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}")
HTTP_PROTOCOLS = ("HTTP/1.0", "HTTP/1.1", "HTTP/2.0", "HTTP/3.0")
API_ROUTE_GROUPS = ("tasks", "stats", "exploration", "logs", "auth", "worker-nodes", "intercept",
                    "conversations", "diagnostics", "llm", "fleet", "task-archives")


def proxy_observation(obj):
    logger, msg = obj.get("logger"), obj.get("msg")
    incomplete = logger == "http.handlers.reverse_proxy" and msg == "aborting with incomplete response"
    if not incomplete and logger != "http.log.error":
        return None
    # Incomplete-response logs use the upstream request. The server's pre-handler
    # error logger can contain original client headers, which cannot identify
    # a request that reached DAO.
    request = obj.get("request")
    if not isinstance(request, dict):
        request = {}
    uri = request.get("uri")
    path = uri.partition("?")[0] if isinstance(uri, str) else ""
    if path.startswith("/api/"):
        group = path[5:].partition("/")[0]
        route = "/api/" + group if group in API_ROUTE_GROUPS else "/api/other"
    else:
        route = "web" if path.startswith("/") else "unknown"
    detail = obj.get("error") if incomplete else msg
    detail = detail.lower() if isinstance(detail, str) else ""
    reason = "unknown"
    for hint, category in (("client disconnected", "client_disconnected"), ("context canceled", "context_canceled"),
                           ("no recent network activity", "network_idle_timeout"), ("deadline exceeded", "deadline"),
                           ("connection refused", "connection_refused"), ("connection reset", "connection_reset"),
                           ("unexpected eof", "unexpected_eof"), ("stream closed", "stream_closed")):
        if hint in detail:
            reason = category
            break
    stage = "response_body" if incomplete else "proxy_error"
    if incomplete and detail.startswith("reading:"):
        stage = "upstream_body_read"
    elif incomplete and detail.startswith("writing:"):
        stage = "downstream_body_write"
    elif not incomplete and detail.startswith("dial ") and reason == "connection_refused":
        stage = "upstream_connect"
    result = {"logger": logger, "msg": "aborting with incomplete response" if incomplete else "proxy request failed",
              "stage": stage, "error": reason, "route_class": route}
    if request.get("proto") in HTTP_PROTOCOLS:
        result["protocol"] = request["proto"]
    if request.get("method") in ("GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"):
        result["method"] = request["method"]
    if type(obj.get("status")) is int and 100 <= obj["status"] <= 599:
        result["status"] = obj["status"]
    if type(obj.get("duration")) in (int, float) and 0 <= obj["duration"] < float("inf"):
        result["duration"] = obj["duration"]
    headers = request.get("headers")
    if incomplete and isinstance(headers, dict):
        values = headers.get("X-Dao-Edge-Id")
        if isinstance(values, list) and len(values) == 1 and isinstance(values[0], str) and EDGE_UUID.fullmatch(values[0]):
            result["edge_id"] = values[0]
    return result


def journal_sample(raw, *, proxy=False, postgres=False):
    row = json.loads(raw)
    at = dt.datetime.fromtimestamp(int(row["__REALTIME_TIMESTAMP"]) / 1000000, dt.timezone.utc)
    message = row.get("MESSAGE")
    if not isinstance(message, str):
        raise ValueError("unsupported journal message")
    if postgres:
        # In journald deployments PostgreSQL can send raw SQL, DETAIL and
        # identifier-bearing errors here as well as to a text log.
        body = message.encode()
        match = PG_HEADER.match(body)
        if match:
            level, text = match[3].decode(), match[4]
        else:
            level_match = re.match(rb"^(ERROR|FATAL|PANIC|LOG|WARNING):\s*(.*)", body)
            level, text = (level_match[1].decode(), level_match[2]) if level_match else ("", b"")
        message = pg_message_class(level, text) or "unclassified_database_record"
    elif message.startswith("{"):
        try:
            obj = json.loads(message)
        except ValueError:
            # Malformed proxy JSON can still contain structured headers.
            message = "[invalid structured journal message]"
        else:
            if not isinstance(obj, dict):
                raise ValueError("unsupported structured journal message")
            safe = proxy_observation(obj) if proxy else None
            if safe is None:
                allowed = ("level", "ts", "logger", "msg", "error", "duration", "status", "err_id", "err_trace")
                safe = {k: obj[k] for k in allowed if type(obj.get(k)) in (str, int, float, bool)}
            message = json.dumps(safe, ensure_ascii=False)
    priority = str(row.get("PRIORITY", ""))
    record = {"ts": at.isoformat(), "priority": priority if priority in "01234567" and len(priority) == 1 else None,
              "text": redact(message)}
    cursor = row.get("__CURSOR")
    return at, cursor if isinstance(cursor, str) else None, (json.dumps(record, ensure_ascii=False) + "\n").encode()


def collect_journal(unit, since, output, until=None):
    import resource
    import time
    units = [unit] if isinstance(unit, str) else list(unit)
    if not units or any(any(c in name for c in "*?[") for name in units):
        raise ValueError("journal collection requires explicit unit names")
    end = until if until is not None else dt.datetime.now(dt.timezone.utc)
    if end <= since:
        raise ValueError("invalid journal time range")
    deadline = time.monotonic() + JOURNAL_TIMEOUT
    windows = min(8, MAX_LINES, MAX_BYTES)
    report = {"units": units, "lines": 0, "bytes_read": 0, "truncated": False, "issues": [],
              "windows": [], "retained_history_before_observation": "unknown"}
    if isinstance(unit, str):
        report["unit"] = unit
    pg_journal = all(name == "postgresql.service" or name.startswith("postgresql@") for name in units)
    args = ["journalctl"]
    for name in units:
        args.extend(["--unit", name])

    def read_window(lo, hi, reverse, byte_limit, row_limit, window):
        # journalctl's inclusive --until needs a one-microsecond adjustment.
        opts = args + ["--since", lo.isoformat(), "--until", hi.isoformat(), "--no-pager",
                       "--output=json", "--output-fields=__REALTIME_TIMESTAMP,__CURSOR,MESSAGE,PRIORITY"]
        if reverse:
            opts.extend(["--reverse", "--lines", str(row_limit)])
        rows = []
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            window["issues"].append("source deadline elapsed")
            return rows, True
        def limits():
            resource.setrlimit(resource.RLIMIT_FSIZE, (byte_limit, byte_limit))
        with tempfile.TemporaryFile() as raw:
            incomplete = False
            try:
                result = subprocess.run(opts, stdout=raw, stderr=subprocess.DEVNULL,
                                        timeout=remaining, preexec_fn=limits)
                if result.returncode and raw.tell() < byte_limit:
                    window["issues"].append("journalctl exit " + str(result.returncode))
                    incomplete = True
            except (OSError, subprocess.TimeoutExpired):
                window["issues"].append("journal query unavailable or timed out")
                incomplete = True
            size = raw.tell()
            report["bytes_read"] += size
            incomplete |= size >= byte_limit
            raw.seek(0)
            for line in raw:
                try:
                    at, cursor, payload = journal_sample(line, proxy=isinstance(unit, str) and unit in ("dao-https", "caddy"), postgres=pg_journal)
                except (ValueError, TypeError, KeyError, OverflowError, OSError):
                    window["invalid_lines"] += 1
                    continue
                if lo <= at <= hi:
                    if len(rows) >= row_limit:
                        incomplete = True
                        break
                    rows.append((at, cursor, payload))
        return rows, incomplete

    with open(output, "wb") as stream:
        for idx in range(windows):
            lo = since + (end - since) * idx / windows
            hi = since + (end - since) * (idx + 1) / windows
            if idx + 1 < windows:
                hi -= dt.timedelta(microseconds=1)
            quota = MAX_LINES * (idx + 1) // windows - MAX_LINES * idx // windows
            budget = MAX_BYTES * (idx + 1) // windows - MAX_BYTES * idx // windows
            window = {"since": lo.isoformat(), "until": hi.isoformat(), "lines": 0,
                      "invalid_lines": 0, "issues": []}
            report["windows"].append(window)
            # Reserve half the raw-byte quota for a reverse query in a dense
            # interval. Sparse intervals need just the forward query.
            first_budget = (budget + 1) // 2
            rows, limited = read_window(lo, hi, False, first_budget, quota, window)
            if limited and budget > first_budget and quota > 1:
                head = rows[:(quota + 1) // 2]
                tail, _ = read_window(lo, hi, True, budget - first_budget, quota // 2, window)
                # Cursors identify records even when timestamps and text match.
                cursors = {c for _, c, _ in head if c}
                rows = head + [entry for entry in reversed(tail)
                               if (not head or entry[0] > head[-1][0] or
                                   (entry[0] == head[-1][0] and entry[1] and entry[1] not in cursors))]
            remaining_bytes = budget
            for at, _, payload in rows:
                if len(payload) > remaining_bytes:
                    limited = True
                    continue
                stream.write(payload)
                remaining_bytes -= len(payload)
                window["lines"] += 1
                window.setdefault("first_at", at.isoformat())
                window["last_at"] = at.isoformat()
            if window["lines"]:
                report.setdefault("first_at", window["first_at"])
                report["last_at"] = window["last_at"]
            report["lines"] += window["lines"]
            if limited or window["issues"] or window["invalid_lines"]:
                window["coverage"] = "partial_sample"
                window["total_records"] = None
                report["truncated"] = True
            else:
                window["coverage"] = "readable_records" if rows else "no_records_observed"
            for issue in window["issues"]:
                if issue not in report["issues"]:
                    report["issues"].append(issue)
    return report

def include_native_report(source, destination):
    """Include only validated, filtered diagnostic JSON from the installed binary."""
    limit = 32 << 20
    with zipfile.ZipFile(source) as archive:
        matches = [entry for entry in archive.infolist() if entry.filename == "diagnostics.json"]
        if len(matches) != 1 or matches[0].file_size > limit:
            raise ValueError("invalid native report size or layout")
        with archive.open(matches[0]) as stream:
            data = json.load(stream)
    if not isinstance(data, dict) or data.get("mode") != "offline":
        raise ValueError("invalid native offline report")
    snapshots = [data[key] for key in ("node", "controller") if data.get(key) is not None]
    if not snapshots:
        raise ValueError("missing native diagnostic snapshot")
    partial = bool(data.get("partial") or data.get("issues"))
    for snapshot in snapshots:
        if not isinstance(snapshot, dict):
            raise ValueError("invalid native snapshot")
        details = snapshot.get("details") or {}
        if not isinstance(details, dict):
            raise ValueError("invalid native snapshot details")
        partial |= bool(snapshot.get("issues"))
        for name in ("log_coverage", "http_log_coverage", "database_log_coverage",
                     "ring_log_coverage", "service_journal"):
            coverage = details.get(name)
            if coverage is None:
                if name in ("log_coverage", "service_journal"):
                    snapshot.setdefault("issues", []).append(name + ": native offline coverage unavailable")
                    partial = True
                continue
            if not isinstance(coverage, dict):
                raise ValueError("invalid native coverage")
            partial |= bool(coverage.get("truncated") or coverage.get("possibly_truncated") or coverage.get("invalid_lines")
                            or coverage.get("issues"))
            optional_absent = name == "http_log_coverage" and coverage.get("available") is False
            if not optional_absent and type(coverage.get("truncated")) is not bool:
                coverage["coverage_unknown"] = True
                partial = True
            if name != "http_log_coverage" and coverage.get("available") is False:
                partial = True
        journal = details.get("service_journal")
        if (isinstance(journal, dict) and isinstance(journal.get("lines"), list)
                and len(journal["lines"]) >= 5000 and journal.get("line_limit_probed") is not True):
            journal["possibly_truncated"] = True
            partial = True
        # Older binaries split multi-line messages before redaction. Only the
        # separate journal supplement can recover trusted entry boundaries.
        if isinstance(journal, dict) and journal.get("lines") and journal.get("format") != "redacted-message-v1":
            journal.pop("lines")
            snapshot.setdefault("issues", []).append("Legacy journal text omitted; see separate journal collection.")
            partial = True
    data["partial"] = partial
    with tempfile.TemporaryDirectory(dir=source.parent) as staging:
        safe = Path(staging) / "filtered.zip"
        with zipfile.ZipFile(safe, "x", compression=zipfile.ZIP_DEFLATED) as result:
            result.writestr("diagnostics.json", json.dumps(redact(data), ensure_ascii=False))
            result.writestr("README.txt", "Filtered offline diagnostics. See collection.json for source coverage.\n")
        # The private staging area and new package belong to the same work
        # directory. Publish only the completed ZIP; never overwrite a file.
        os.link(safe, destination)
    return partial


UNLINKED_PROCESS_LIMIT = 1024
UNLINKED_FD_LIMIT = 32768
UNLINKED_SECONDS = 2.0


def collect_unlinked_files(scopes, proc_root=Path("/proc")):
    """One metadata-only pass over visible process FDs on the selected devices."""
    report = {
        "observed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "scope": "visible_process_fds_on_selected_filesystems",
        "process_limit": UNLINKED_PROCESS_LIMIT, "fd_limit": UNLINKED_FD_LIMIT,
        "seconds_budget": UNLINKED_SECONDS, "processes_seen": 0, "fd_directories_read": 0, "fds_seen": 0,
        "scan_available": False, "limit_reached": None, "disappeared": 0,
        "permission_denied": 0, "other_read_errors": 0, "partial": False,
        "unavailable_scopes": [], "filesystems": [],
    }
    by_device = {}
    for label, directory in scopes.items():
        try:
            device = os.stat(directory).st_dev if directory is not None else None
        except OSError:
            device = None
        if device is None:
            report["unavailable_scopes"].append(label)
            continue
        if device not in by_device:
            by_device[device] = {"scopes": [], "observed_files": 0, "fd_references": 0,
                                 "observed_allocated_bytes": 0, "observed_apparent_bytes": 0}
        by_device[device]["scopes"].append(label)
    report["filesystems"] = list(by_device.values())
    seen = set()
    deadline = time.monotonic() + UNLINKED_SECONDS

    def missed(error):
        if isinstance(error, (FileNotFoundError, ProcessLookupError)):
            report["disappeared"] += 1
        elif isinstance(error, PermissionError):
            report["permission_denied"] += 1
        else:
            report["other_read_errors"] += 1

    try:
        with os.scandir(proc_root) as processes:
            for process in processes:
                if time.monotonic() >= deadline:
                    report["limit_reached"] = "elapsed"
                    break
                if not process.name.isdecimal():
                    continue
                if report["processes_seen"] >= UNLINKED_PROCESS_LIMIT:
                    report["limit_reached"] = "processes"
                    break
                report["processes_seen"] += 1
                try:
                    with os.scandir(os.path.join(process.path, "fd")) as descriptors:
                        report["fd_directories_read"] += 1
                        report["scan_available"] = True
                        for fd in descriptors:
                            if time.monotonic() >= deadline:
                                report["limit_reached"] = "elapsed"
                                break
                            if report["fds_seen"] >= UNLINKED_FD_LIMIT:
                                report["limit_reached"] = "fds"
                                break
                            report["fds_seen"] += 1
                            # procfs magic links support stat even after unlink.
                            # Never open a target or read its path, name or contents.
                            try:
                                metadata = fd.stat()
                            except OSError as error:
                                missed(error)
                                continue
                            group = by_device.get(metadata.st_dev)
                            if group is None or metadata.st_nlink or not stat.S_ISREG(metadata.st_mode):
                                continue
                            group["fd_references"] += 1
                            identity = (metadata.st_dev, metadata.st_ino)
                            if identity not in seen:
                                seen.add(identity)
                                group["observed_files"] += 1
                                group["observed_allocated_bytes"] += metadata.st_blocks * 512
                                group["observed_apparent_bytes"] += metadata.st_size
                except OSError as error:
                    missed(error)
                if report["limit_reached"]:
                    break
    except OSError as error:
        missed(error)
    if not report["scan_available"]:
        for group in by_device.values():
            for field in ("observed_files", "fd_references", "observed_allocated_bytes", "observed_apparent_bytes"):
                group[field] = None
    report["partial"] = bool(not report["scan_available"] or report["unavailable_scopes"] or report["limit_reached"] or
                             report["disappeared"] or report["permission_denied"] or report["other_read_errors"])
    return report


def main(contents, roles, hours, until_text=None):
    contents=Path(contents)
    now=dt.datetime.now(dt.timezone.utc)
    until=parse_time(until_text) if until_text else now
    if until is None or until>now:
        raise ValueError("window end must be a past ISO 8601 timestamp with a timezone")
    since=until-dt.timedelta(hours=hours)
    report={"collected_at":now.isoformat(),"since":since.isoformat(),"until":until.isoformat(),"max_lines_per_source":MAX_LINES,"max_bytes_per_source":MAX_BYTES,"sources":{},"issues":[]}
    units=[]
    disk_scopes = {"root": Path("/")}
    for role in roles.split("-"):
        if role not in ("main", "worker"):
            continue
        # Native output stays private until it has passed the current filter.
        native = contents.parent / "native" / (role + ".zip")
        native_status = {"available": False, "partial": True}
        report["sources"][role + "-native"] = native_status
        if native.exists():
            try:
                native_status["partial"] = include_native_report(native, contents / (role + ".zip"))
                native_status["available"] = True
            except (OSError, ValueError, RuntimeError, TypeError, AttributeError, EOFError, zipfile.BadZipFile):
                report["issues"].append(role + ": native report omitted after validation failed")
        else:
            report["issues"].append(role + ": native report unavailable")
        disk_scopes[role + "_data"] = None
        root=Path("/var/lib/dao/data")
        if role=="worker":
            try:
                with regular_open(Path("/etc/dao-worker/config.json"),Path("/etc/dao-worker")) as f:
                    cfg=json.loads(f.read(1<<20))
                root=Path(cfg["data_dir"])
                if not root.is_absolute():raise ValueError("worker data_dir must be absolute")
            except (OSError,ValueError,KeyError) as error:
                report["issues"].append("worker path unavailable: "+redact(str(error)));continue
        disk_scopes[role + "_data"] = root
        for name,relative in (("system","diagnostics"),("http","diagnostics/http")):
            key=role+"-"+name
            source=collect_files(root,relative,since,contents/(key+".jsonl"),until)
            if name == "system" and source.get("available") is False:
                source.setdefault("issues", []).append("system log files unavailable")
            report["sources"][key]=source
        units.extend(["dao", "dao-https"] if role=="main" else ["dao-worker"])
    unlinked = collect_unlinked_files(disk_scopes)
    (contents/"unlinked-files.json").write_text(json.dumps(unlinked, indent=2)+"\n")
    report["sources"]["unlinked-files"] = {"partial":unlinked["partial"], "file":"unlinked-files.json"}
    # Database startup/error logs and optional domain-based Caddy use only unit journals.
    units.append("caddy")
    for unit in units:
        key="journal-"+unit.replace("*","clusters")
        report["sources"][key]=collect_journal(unit,since,contents/(key+".jsonl"),until)
    db_units,db_issues=database_units(contents/"status.txt")
    exit_evidence = collect_postgres_exit(db_units, since, until)
    if db_issues:
        exit_evidence["issues"].extend(db_issues)
        exit_evidence["partial"] = True
    report["sources"]["postgresql-exit"] = {"partial":exit_evidence["partial"], "file":"postgresql-exit.json"}
    (contents/"postgresql-exit.json").write_text(json.dumps(exit_evidence, indent=2)+"\n")
    key="journal-postgresql@clusters"
    report["sources"][key]=collect_journal(db_units,since,contents/(key+".jsonl"),until)
    report["sources"][key]["issues"].extend(db_issues)
    report["partial"]=bool(report["issues"]) or any(x.get("partial") or x.get("issues") or x.get("truncated") or x.get("invalid_lines") for x in report["sources"].values())
    (contents/"collection.json").write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n")
    total=sum(x.get("lines",0) for x in report["sources"].values())
    print(f"补充采集 {since.isoformat()} 至 {until.isoformat()}：{total} 条记录；各来源行数、时间范围和截断情况见 collection.json。")
    if report["partial"]:print("部分来源读取失败或达到限额，已明确记录；原始日志未修改。")

if __name__=="__main__":
    main(sys.argv[1],sys.argv[2],int(sys.argv[3]),sys.argv[4] if len(sys.argv)>4 else None)
DAO_DIAGNOSTIC_COLLECT_PYTHON
  then
    printf '补充采集异常；未过滤的原生导出仅保存在本地。\n'
    printf 'supplement collection failed\n' >"$contents/collection-error.txt"
    failures=$((failures + 1))
  fi
else
  printf 'python3 unavailable; native reports kept privately, logs omitted\n' >"$contents/collection-error.txt"
  failures=$((failures + 1))
fi

cat >"$contents/README.txt" <<'INFO'
DAO 按需诊断包：status.txt 为采集时的操作系统/服务状态；main.zip、worker.zip
使用已安装程序的离线导出，经当前脚本过滤后才纳入此包；旧版拆行 journal 由单独的日志采集覆盖。
未经处理的原生 ZIP 和命令输出仅位于本机工作目录的 native/ 子目录。
额外的 main/worker-system.jsonl、*-http.jsonl 和 journal-*.jsonl 不受旧版 200 行限制。
补充采集默认最近 24 小时，可用 --hours 与 --until 指定仍有日志的历史窗口；collection.json 列明各来源范围、条数、读取失败和截断。
unlinked-files.json 汇总采集时可见进程中、位于根盘或角色数据盘上、仍由文件描述符持有的已删除常规文件。同一盘和重复描述符只计一次，分列已分配空间及逻辑长度。限额、权限或进程退出产生的缺口均标记。统计包括匿名临时文件，只观察当前 PID 命名空间可见描述符；仅由内存映射持有的文件不在范围内。时间预算在系统调用间检查，分配块数不代表可释放容量。输出不含文件名、路径和进程编号。
postgresql-exit.json 记录采集时实例状态与上次进程退出时间、当前和未压缩前一份默认 PG 日志的采样区间、首末时间及分类计数。同一文件中的 wal_space 只读核对 Debian 默认实例目录内常规 WAL 段文件的逻辑和分配字节。目录自定义、不可读或含链接等情况不能据此断言当前实例的 WAL 为零。原始 SQL、段名称、角色和数据不在该文件中，首因须另行核实。
系统文件与 journal 可能记录同一事件，分析时不要重复计数。缺少 http 文件在 rc.3 为正常情况。
不声称收集数据库中的全部历史，轮转前已删除的记录不能恢复；任何限额都在清单中标明。
缺少某角色表示本机未安装该角色；*-export.txt 记录导出结果，失败时保留部分信息。
诊断 ZIP 中 partial/issues 说明缺失项。服务不存在或当前系统不支持某命令，也会记录。
不含完整配置、密码文件、数据库备份、任务目录或全量模型/工具录制。
常见日志凭据由 DAO 脱敏；业务内容和未标注的秘密仍需在分享前检查。
离线导出不连接数据库或主站，不能仅凭本包证明每个任务、模型和 MCP 都正常。
脚本不安装软件、不更改服务、不升级；只有显式 --upload 才上传到私有 GitHub。
上传凭据不进入本包，原始应用日志保持不变；上传回执另存于包旁 upload-receipt.json。
INFO

archive=$work/dao-diagnostics.tar.gz
tar -czf "$archive" -C "$contents" .
chmod 600 "$archive"
trap - ERR
if (( failures > 0 )); then
  printf '\n已生成部分诊断包（%s 个角色导出异常）。\n' "$failures"
else
  printf '\n诊断包已生成。\n'
fi
if (( upload )); then
  printf '本地诊断备份：%s\n' "$archive"
  command -v python3 >/dev/null || { echo '上传需要 python3；本地诊断包已保留。' >&2; exit 1; }
  python3 - "$archive" "$repo" "$token_file" "$roles" <<'DAO_DIAGNOSTIC_UPLOAD_PYTHON'
"""Upload an explicitly requested diagnostic bundle to a private GitHub release."""
import datetime
import getpass
import hashlib
import json
import os
from pathlib import Path
import re
import secrets
import socket
import stat
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
import warnings

MAX_BUNDLE = 16 << 20
DEFAULT_REPO = os.environ.get("DAO_DIAGNOSTICS_REPO", "").strip()


class UploadError(Exception):
    def __init__(self, message, status=0):
        super().__init__(message)
        self.status = status


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class GitHub:
    def __init__(self, token):
        self.token = token
        self.http = urllib.request.build_opener(NoRedirect())

    def request(self, method, url, value=None, binary=False):
        parts = urllib.parse.urlsplit(url)
        if parts.scheme != "https" or parts.netloc not in ("api.github.com", "uploads.github.com"):
            raise UploadError("拒绝向非 GitHub API 地址发送授权。")
        body = value if binary else json.dumps(value).encode() if value is not None else None
        request = urllib.request.Request(url, data=body, method=method, headers={
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "DAO-diagnostics",
            "Content-Type": "application/gzip" if binary else "application/json",
        })
        request.add_unredirected_header("Authorization", "Bearer " + self.token)
        try:
            with self.http.open(request, timeout=60) as response:
                data = response.read((2 << 20) + 1)
            if len(data) > 2 << 20:
                raise UploadError("GitHub 返回超出大小限制的响应。")
            return json.loads(data)
        except urllib.error.HTTPError as error:
            if error.code in (401, 403):
                message = "GitHub 授权不足或受到限流：需要诊断仓库 Contents 读写权限，安装只读 Token 不够。"
            elif error.code == 404:
                message = "找不到私有诊断仓库/资源，或当前 Token 没有访问权限。"
            else:
                message = "GitHub 请求失败（HTTP %s），本地诊断包已保留。" % error.code
            raise UploadError(message, error.code) from None
        except (OSError, ValueError) as error:
            # Remote response bodies and exception strings can contain credentials.
            raise UploadError("GitHub 网络或响应异常，本地诊断包已保留。") from None


def read_token(path):
    if path:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd) as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o077:
                raise UploadError("Token 文件必须属于 root，且其他用户不可读写（建议权限 0600）。")
            token = stream.read(8193).strip()
    else:
        # Fail instead of falling back to echoed stdin when run through curl/cron.
        with warnings.catch_warnings():
            warnings.simplefilter("error", getpass.GetPassWarning)
            try:
                # getpass opens the controlling TTY using unbuffered FileIO.
                # open('/dev/tty', 'w+') requires seeking and fails even on an
                # interactive SSH terminal; stdin may also be the script pipe.
                token = getpass.getpass("诊断仓库 GitHub 写入 Token（隐藏输入，不保存）：").strip()
            except (OSError, getpass.GetPassWarning, EOFError):
                raise UploadError("无法隐藏输入 Token；请使用 --token-file 指定 root-only 的诊断授权文件。") from None
    if not token or len(token) > 8192 or any(c.isspace() for c in token) or not token.isascii():
        raise UploadError("GitHub Token 格式无效。")
    return token


def save_receipt(path, value):
    fd, temporary = tempfile.mkstemp(prefix=".receipt-", dir=path.parent)
    try:
        with os.fdopen(fd, "w") as stream:
            json.dump(value, stream, ensure_ascii=False, indent=2)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def verify_asset(asset, name, size, digest):
    if (not isinstance(asset, dict) or not isinstance(asset.get("id"), int) or asset["id"] <= 0
            or asset.get("name") != name or asset.get("state") != "uploaded"
            or asset.get("size") != size or asset.get("digest") != "sha256:" + digest):
        raise UploadError("远端文件尚未通过大小和 SHA-256 核验，未标记上传成功。")


def upload(archive, repo, token, roles, client=None):
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]{1,100}", repo):
        raise UploadError("诊断仓库必须为 owner/repository。")
    if roles not in ("main", "worker", "main-worker"):
        raise UploadError("诊断角色无效。")
    with archive.open("rb") as stream:
        if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
            raise UploadError("诊断包不是普通文件。")
        data = stream.read(MAX_BUNDLE + 1)
    if not data or len(data) > MAX_BUNDLE:
        raise UploadError("诊断包为空或超过 16 MiB，未上传。")
    client = client or GitHub(token)
    base = "https://api.github.com/repos/" + repo
    identity = client.request("GET", base)
    if (not isinstance(identity, dict) or identity.get("private") is not True
            or str(identity.get("full_name", "")).lower() != repo.lower()):
        raise UploadError("目标不是指定的私有仓库，拒绝上传诊断日志。")

    now = datetime.datetime.now(datetime.timezone.utc)
    tag = "diagnostics-" + now.strftime("%Y-%m-%d")
    host = re.sub(r"[^A-Za-z0-9.-]", "-", socket.gethostname())[:48] or "host"
    reference = roles + "-" + host + "-" + now.strftime("%Y%m%dT%H%M%SZ") + "-" + secrets.token_hex(4)
    name = "dao-" + reference + ".tar.gz"
    digest = hashlib.sha256(data).hexdigest()
    receipt_path = archive.parent / "upload-receipt.json"
    receipt = {"id": reference, "repository": repo, "tag": tag, "asset": name,
               "bytes": len(data), "sha256": digest, "state": "pending"}
    save_receipt(receipt_path, receipt)
    release_url = base + "/releases/tags/" + tag
    try:
        release = client.request("GET", release_url)
    except UploadError as error:
        if error.status != 404:
            raise
        try:
            release = client.request("POST", base + "/releases", {
                "tag_name": tag, "name": "DAO diagnostics " + now.strftime("%Y-%m-%d") + " (UTC)",
                "body": "On-demand private diagnostic bundles; not application releases.",
                "draft": False, "prerelease": True, "make_latest": "false",
            })
        except UploadError as error:
            if error.status != 422:
                raise
            release = client.request("GET", release_url)  # Another VPS created today's release.
    release_id = release.get("id") if isinstance(release, dict) else None
    if not isinstance(release_id, int) or release_id <= 0 or release.get("tag_name") != tag:
        raise UploadError("诊断发行记录身份无效。")
    url = "https://uploads.github.com/repos/" + repo + "/releases/%d/assets?" % release_id + urllib.parse.urlencode({"name": name})
    try:
        asset = client.request("POST", url, data, binary=True)
    except UploadError as error:
        if error.status not in (0, 408, 409, 422, 500, 502, 503, 504):
            raise
        # A lost upload response is not proof of failure. Reconcile by unique ID
        # and digest; never overwrite or blindly send the same bundle again.
        asset = None
        for page in range(1, 11):
            assets = client.request("GET", base + "/releases/%d/assets?per_page=100&page=%d" % (release_id, page))
            if not isinstance(assets, list):
                raise UploadError("无法核查上传结果。")
            asset = next((a for a in assets if isinstance(a, dict) and a.get("name") == name), None)
            if asset or len(assets) < 100:
                break
        if asset is None:
            raise UploadError("无法确认上传结果；已保留本地包及编号，请检查私有仓库。") from None
    verify_asset(asset, name, len(data), digest)
    receipt.update(state="uploaded", asset_id=asset.get("id"),
                   url="https://github.com/" + repo + "/releases/tag/" + tag)
    save_receipt(receipt_path, receipt)
    return receipt


def main():
    token = ""
    try:
        archive, repo, token_file, roles = sys.argv[1:]
        if not token_file and Path("/etc/dao-diagnostics/github-token").exists():
            token_file = "/etc/dao-diagnostics/github-token"
        token = read_token(token_file)
        receipt = upload(Path(archive), repo, token, roles)
        print("上传已核验，诊断编号：" + receipt["id"])
        print("私有诊断位置：" + receipt["url"])
        print("把这个编号告诉维护者即可，无需下载再上传诊断包。")
        return 0
    except UploadError as error:
        print(str(error), file=sys.stderr)
    except (OSError, ValueError):
        print("读取上传参数、授权或文件失败；本地诊断包已保留。", file=sys.stderr)
    finally:
        token = ""
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
DAO_DIAGNOSTIC_UPLOAD_PYTHON
else
  printf '请下载并发送这个文件：%s\n' "$archive"
fi
